import {connection,api,extract,normalizeExplanation} from './api.js';
import {reports,labels,explain,validateFile,ocrService,translationService,speechService,audioText} from './services.js';
const native=globalThis.HealthClearAndroid;
document.body.classList.toggle('android-app',!!native);
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let cloudSession='',cloudEmail='';
let current=null,lang='en',page='upload',result=null,objectURL=null,operation=0;
const offlineMessage='Connect your backend in Settings to analyze personal reports. Fictional samples work offline.';
const notice='Fictional sample · This example does not use live AI.';
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',6500);}
function steps(n){return `<div class="steps" aria-label="Report progress">${['Upload report','Review text','Understand'].map((s,i)=>`${i?'<span class="rule"></span>':''}<span class="step ${i===n?'on':''}"><b>${i+1}</b>${s}</span>`).join('')}</div>`;}
function language(){return `<label for="language">Explanation language</label><select id="language"><option value="en" ${lang==='en'?'selected':''}>English</option><option value="hi" ${lang==='hi'?'selected':''}>हिन्दी · Hindi</option><option value="te" ${lang==='te'?'selected':''}>తెలుగు · Telugu</option></select>`;}
function bindLanguage(fn){$('#language').onchange=e=>{lang=e.target.value;speechService.stop();fn?.();};}
function clear(){operation++;native?.closeReport();speechService.stop();if(objectURL)URL.revokeObjectURL(objectURL);objectURL=null;current=null;result=null;}
function render(route){page=route;document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===route));if(route==='history')history();else if(route==='settings')settings();else upload();}
function upload(){page='upload';document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav==='upload'));clear();$('#app').innerHTML=`<section class="intro"><div><div class="eyebrow">Clarity for your health journey</div><h1>Your medical report.<br><em>In words you understand.</em></h1><p>Make sense of medical terms, one report at a time. Get a simple explanation, in your language, at your pace.</p></div><div class="illustration" aria-hidden="true"><div class="paper"><b>+</b><i></i><i></i><i></i><span>✓</span></div></div></section>${steps(0)}<div class="workspace"><section class="card"><h2>Let’s start with your report</h2><p class="sub">Blood tests, written X-ray reports, and ultrasound reports.</p><div class="connection-status">${connection.ready?'● Backend connected for this session':'○ Local mode · Connect a backend in Settings'}</div><div class="drop" id="drop"><div class="upload-icon" aria-hidden="true">↥</div><h3>Choose your written report</h3><p>Take a clear photo or select a report from your device</p><div class="buttonrow"><button class="primary" id="choose">↥ &nbsp; Choose a file</button><button id="camera">▣ &nbsp; Use camera</button></div><div class="formats">JPG, PNG or PDF · Up to 10 MB</div><input hidden id="file" type="file" accept="image/jpeg,image/png,application/pdf"><input hidden id="capture" type="file" accept="image/jpeg,image/png" capture="environment"></div><div class="privacy-box"><span aria-hidden="true">♧</span><p><strong>Your report stays yours.</strong> No-save is the default. Files remain on this device unless you enable processing below. With a connected backend, the file and reviewed text are sent to your server and OpenAI. This backend does not persist reports; provider retention applies (typically up to 30 days for abuse monitoring, with exceptions). No training opt-in is included. Temporary Android cache is cleared when leaving the report or at the next launch. <a href="#settings">Data & privacy details</a></p></div><label class="consent"><input type="checkbox" id="consent">${connection.ready?'I consent to sending this report to my configured backend and OpenAI for extraction, explanation, translation and follow-up questions. I understand the retention notice.':'I understand that this file stays local. Connect a backend in Settings for extraction and analysis.'}</label><p class="fine">Have a scan image? Please use the accompanying written report. HealthClear does not interpret medical images.</p><div id="error" role="alert"></div></section><aside class="card sample-card"><span class="tag">TAKE A LOOK AROUND</span><h2>A little curious?<br>Try a sample report.</h2><p>Explore how an explanation works before using a report of your own.</p><div class="sample-types"><button data-sample="blood">▤ &nbsp; Blood test <span>↗</span></button><button data-sample="xray">▧ &nbsp; Written X-ray report <span>↗</span></button><button data-sample="ultrasound">▥ &nbsp; Written ultrasound report <span>↗</span></button></div><p class="fine">FICTIONAL DEMO<br>Samples and explanations are prewritten examples, not real analysis or medical advice.</p></aside></div><section class="benefits"><div class="benefit"><span class="symbol">Aa</span><div><h3>Your language. Your pace.</h3><p>Read in English, Hindi, or Telugu.<br>Listen when that feels easier.</p></div></div><div class="benefit"><span class="symbol">≡</span><div><h3>Connected to the source</h3><p>See exactly where each finding<br>comes from in your report.</p></div></div><div class="benefit"><span class="symbol">♡</span><div><h3>A better doctor conversation</h3><p>Bring clearer questions and a<br>simple summary to your next visit.</p></div></div></section><div class="disclaimer">HealthClear helps you understand written reports. It does not diagnose conditions, prescribe treatment, or replace a healthcare professional’s assessment.</div>`;
$('#choose').onclick=()=>pick('file');$('#camera').onclick=()=>pick('capture');['file','capture'].forEach(id=>$('#'+id).onchange=e=>loadFile(e.target.files[0]));$('#drop').ondragover=e=>e.preventDefault();$('#drop').ondrop=e=>{e.preventDefault();loadFile(e.dataTransfer.files[0]);};document.querySelectorAll('[data-sample]').forEach(b=>b.onclick=()=>sample(b.dataset.sample));}
function pick(id){if(!$('#consent').checked){toast('Please read and accept the processing notice first.');$('#consent').focus();return;}if(native){native.pickFile(id==='capture');return;}$('#'+id).click();}
function sample(id){clear();current={id,name:reports[id].name,text:reports[id].lines.join('\n'),demo:true};review();}
async function loadFile(file){
 if(!$('#consent')?.checked){toast('Please accept the processing notice first.');return;}
 try{await validateFile(file);}catch(e){$('#error').textContent=e.message;return;}
 const consent=connection.ready;
 objectURL=URL.createObjectURL(file);current={name:file.name,type:file.type,file,demo:false,text:'',consent,ocrStatus:consent?'Extracting written text…':'OCR unavailable. Type the written report exactly, or connect a backend first.',busy:consent};
 review();if(consent)await runOcr();
}
async function runOcr(){
 const target=current,version=++operation;target.busy=true;$('#continue').disabled=true;$('#retry-ocr').disabled=true;$('#ocr-status').textContent='Extracting written text securely…';$('#ocr-status').setAttribute('aria-busy','true');
 try{const output=await extract(target.file);if(version!==operation||target!==current)return;
  target.blocked=output.documentType!=='written_report';
  target.text=output.lines.map(l=>l.uncertain&&!l.text.includes('[unreadable]')?l.text+' [unreadable]':l.text).join('\n');
  target.ocrStatus=target.blocked?'This is not a readable written medical report. Upload the accompanying written report; medical scans are not interpreted.':output.lines.some(l=>l.uncertain)?'Some text is uncertain and marked [unreadable]. Obtain a clearer copy; never guess missing numbers.':'Text extracted. Check every number, unit, reference range and qualifier against the original before continuing.';
  $('#extracted').value=target.text;$('#verified').checked=false;
 }catch(e){if(target!==current)return;target.ocrStatus=e.message+' You can retry extraction or transcribe the written report exactly.';}
 finally{if(target===current&&page==='review'){target.busy=false;$('#ocr-status').textContent=target.ocrStatus;$('#ocr-status').setAttribute('aria-busy','false');$('#retry-ocr').disabled=false;$('#continue').disabled=!!target.blocked;}}
}
function setupPdf(){if(native&&!current.demo&&current.type==='application/pdf'&&$('#pdf-page')){current.pdfPage=0;$('#pdf-prev').onclick=()=>native.pdfPage(current.pdfPage-1);$('#pdf-next').onclick=()=>native.pdfPage(current.pdfPage+1);native.pdfPage(0);}}
function sourceLines(){return current.text.split(/\r?\n/).map((line,i)=>`<div id="source-${i}" tabindex="-1" class="source-line"><small>${i+1}</small> &nbsp;${esc(line)}</div>`).join('');}
function original(){if(current.saved)return '<p class="fine">Saved reviewed text. The original file was not stored.</p>'+sourceLines();if(native&&!current.demo&&current.type==='application/pdf')return `<div class="toolbar"><button id="pdf-prev">← Previous</button><span id="pdf-number"></span><button id="pdf-next">Next →</button></div><img id="pdf-page" alt="Original PDF page"><p class="fine">PDF pages are rendered on your device. Review all relevant pages.</p>`;if(current.demo)return `<div class="banner">Fictional sample · No patient data</div>${reports[current.id].lines.map((s,i)=>`<div id="source-${i}" tabindex="-1" class="source-line"><small>${String(i+1).padStart(2,'0')}</small> &nbsp;${esc(s)}</div>`).join('')}`;return current.type==='application/pdf'?`<object data="${objectURL}" type="application/pdf" aria-label="Original PDF"><a href="${objectURL}" target="_blank" rel="noopener">Open original PDF</a></object>`:`<img src="${objectURL}" alt="Uploaded report for manual review">`;}
function review(){operation++;page='review';$('#app').innerHTML=`<div class="eyebrow">Make sure the details are right</div><h1>Review before you continue.</h1>${steps(1)}<div class="banner" id="ocr-status" role="status" aria-busy="${!!current.busy}">${current.demo?'Fictional demo · Sample text is prefilled; no OCR was performed.':esc(current.ocrStatus||'Review the text below.')}</div><div class="workspace"><section class="card"><h2>Review the report text</h2><p class="sub">Never fill in a number you cannot read. Use [unreadable] and obtain a clearer copy instead.</p><label for="extracted">${current.demo?'Sample report text':'Extracted / manually corrected report text'}</label><textarea id="extracted" spellcheck="false">${esc(current.text)}</textarea><div class="toolbar">${language()}</div><label class="consent"><input id="verified" type="checkbox">I checked all text, numbers, units, and uncertainty against the original.</label><div id="review-error" role="alert"></div><div class="toolbar"><button class="primary" id="continue" ${current.busy||current.blocked?'disabled':''}>Explain this report →</button><button id="back">Back to upload</button>${!current.demo&&current.file&&current.consent?'<button id="retry-ocr">Retry extraction</button>':''}</div><p class="fine">${current.demo?'Sample explanations are prewritten. Edited samples cannot use a fictional explanation.':'AI extraction may make mistakes. Verify the original first. Do not continue with unreadable or missing details.'}</p></section><aside class="card original"><h2>Original document</h2><p class="sub">${esc(current.name)}</p>${original()}</aside></div>`;bindLanguage();setupPdf();if($('#retry-ocr'))$('#retry-ocr').onclick=runOcr;$('#back').onclick=upload;$('#extracted').oninput=()=>{$('#verified').checked=false;if(!current.demo)current.text=$('#extracted').value;};
 $('#continue').onclick=async()=>{
  const t=$('#extracted').value,error=$('#review-error');error.textContent='';
  if(current.busy||current.blocked)return;
  if(!t.trim()||/\[unreadable\]|\?\?/i.test(t)){error.textContent='Resolve missing or unreadable text from a clearer written report. Do not guess.';return;}
  if(!$('#verified').checked){error.textContent='Verify all text against the original first.';return;}
  const target=current,version=++operation;$('#continue').disabled=true;$('#continue').textContent='Preparing explanation…';
  try{if(target.demo)result=explain(target.id,t,lang);else{if(!target.consent)throw Error('Return to Upload after connecting a backend in Settings and accept processing consent.');const data=await api('explain',{text:t,language:lang,consent:true});if(version!==operation||current!==target)return;result=normalizeExplanation(data,t,lang,labels);}
   target.text=t;target.result=result;target.resultLang=lang;results();
  }catch(e){if(current===target&&page==='review'){error.textContent=e.message;$('#continue').disabled=false;$('#continue').textContent='Retry explanation →';}}
 };
}
function source(ref){if(ref===null||ref===undefined)return '';return `<a href="#source-${ref}" data-source="${ref}" class="source-link">↗ ${esc(result.labels.source)} · ${ref+1}</a>`;}
function results(){page='results';document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav==='upload'));if(current.demo)result=translationService.get(current.id,current.text,lang);else result=current.result;const e=result,l=e.labels;$('#app').innerHTML=`<div class="eyebrow">A clearer picture, one detail at a time</div><h1>Your report, made simpler.</h1>${steps(2)}<div class="banner">${current.demo?notice+' This explanation is prewritten educational content.':'AI-generated explanation of your reviewed text. Verify it with the report and a healthcare professional; errors are possible.'}</div><div class="toolbar">${language()}<button id="download">↓ Doctor-visit summary</button><button id="save">♡ Save to My Reports</button><button id="cloud-save">Save text to cloud</button><button id="new">New report</button></div><p class="fine">No-save is the default. Saving on Android stores reviewed text and explanation encrypted on this device, not the original file. Export only if you want a separate copy.</p><div class="workspace"><section class="card"><div id="explanation" lang="${lang}"><h2>${l.summary}</h2><p>${esc(e.summary)}</p>${e.findings.map(f=>source(f.ref)).join(' ')}<h2 style="margin-top:25px">${l.finding}</h2>${e.findings.map(f=>`<div class="finding"><p>${esc(f.text)}</p>${f.quote?`<blockquote class="exact-quote"><small>Exact source text · values and units unchanged</small><br>${esc(f.quote)}</blockquote>`:''}${f.value?`<p><strong>${esc(f.value)}</strong></p><p class="fine">Value · Reference range (exactly as printed)</p>`:''}${f.rangeText?`<span class="chip">${esc(f.rangeText)}</span><br>`:''}${f.outside?`<span class="chip">↓ ${l.outside}</span><br>`:''}${source(f.ref)}</div>`).join('')}<div class="finding"><h3>${l.limits}</h3><p>${esc(l.limit)}</p></div><div class="finding"><h3>${l.terms}</h3><p class="preserve-lines">${esc(e.terms)}</p></div><div class="finding"><h3>${l.follow}</h3><p class="preserve-lines">${esc(e.follow)}</p>${(e.followRefs||[e.followRef]).map(source).join(' ')}</div><div class="finding"><h3>${l.questions}</h3><p class="preserve-lines">${esc(e.questions)}</p></div><p>${l.context}</p></div><div class="audio"><p>AI-generated audio · Device text-to-speech reads the displayed explanation. Voice availability depends on your device. Android uses installed offline voices.</p><div class="buttonrow"><button id="play">▶ Play</button><button id="pause">Ⅱ Pause</button><button id="replay">↻ Replay</button><label>Speed <select id="speed"><option value="0.8">0.8×</option><option selected value="1">1×</option><option value="1.25">1.25×</option><option value="1.5">1.5×</option></select></label></div><div id="audio-status" role="status"></div></div><h2>Ask about this report</h2><p class="sub">${current.demo?'Suggested answers are prewritten for this fictional sample.':'Answers are based on the reviewed report text, with source references. Unanswered questions belong with your clinician.'}</p><div class="questions">${['What does this term mean?','Which results are outside the listed ranges?','What should I ask my doctor?','Does the report recommend a follow-up?'].map((q,i)=>`<button data-question="${i}">${q}</button>`).join('')}</div><form id="ask"><label for="question">Your question</label><div class="toolbar"><input id="question" type="text" maxlength="500" required placeholder="Ask about the written report"><button class="primary">Ask →</button></div></form><div id="answer" role="status"></div></section><aside class="card original"><h2>Original report</h2><p class="sub">${esc(current.name)} · Source text</p>${original()}${!current.demo&&!current.saved?'<h3>Reviewed source text</h3>'+sourceLines():''}</aside></div>`;
 setupPdf();bindLanguage(changeResultLanguage);bindSources();$('#new').onclick=upload;$('#download').onclick=download;$('#save').onclick=save;$('#cloud-save').onclick=saveCloud;$('#play').onclick=()=>play(false);$('#replay').onclick=()=>play(true);$('#pause').onclick=()=>{if(native)native.pause();else globalThis.speechSynthesis?.pause();$('#audio-status').textContent='Paused';};$('#speed').onchange=()=>{speechService.stop();$('#audio-status').textContent='Speed changed. Press Play to restart.';};document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>answer(+b.dataset.question));$('#ask').onsubmit=ev=>{ev.preventDefault();askLive($('#question').value);};}
async function changeResultLanguage(){
 if(current.demo){results();return;}
 if(!current.consent){lang=current.resultLang;toast('Accept the saved-report processing notice before requesting a new translation.');if($('#language'))$('#language').value=lang;return;}
 if(!connection.ready){lang=current.resultLang;toast('Connect a backend to translate a personal report.');results();return;}
 const target=current,version=++operation;const requestedLang=lang;lang=target.resultLang;$('#language').disabled=true;toast('Preparing the explanation in your language…');
 try{const data=await api('explain',{text:target.text,language:requestedLang,consent:target.consent===true});if(version!==operation||current!==target)return;lang=requestedLang;target.result=normalizeExplanation(data,target.text,lang,labels);target.resultLang=lang;results();}catch(e){if(current===target){lang=target.resultLang;results();toast(e.message);}}
}
async function askLive(question){
 if(current.demo){$('#answer').className='answer';$('#answer').textContent='Free-text chat needs a connected backend and a personal report. Use the suggested questions for this fictional sample.';return;}
 if(!current.consent){toast('Accept the saved-report processing notice before sending a question.');return;}
 if(current.chatBusy)return;current.chatBusy=true;const target=current;document.querySelectorAll('[data-question]').forEach(b=>b.disabled=true);$('#answer').className='answer';$('#answer').textContent='Reading the report…';$('#answer').setAttribute('aria-busy','true');$('#ask button').disabled=true;
 try{const answer=await api('chat',{text:target.text,language:lang,question,consent:target.consent===true});if(target!==current||page!=='results')return;$('#answer').innerHTML=`${!answer.enoughInformation?'<p>The report does not contain enough information to answer fully.</p>':''}${answer.claims.map(c=>`<p lang="${lang}">${esc(c.text)}</p><blockquote class="exact-quote">${esc(c.quote)}</blockquote>${source(c.ref)}`).join('')}${answer.education?`<p><strong>General education</strong><br>${esc(answer.education)}</p>`:''}`;bindSources();}catch(e){if(target===current&&$('#answer'))$('#answer').textContent=e.message;}finally{target.chatBusy=false;if(target===current&&$('#answer')){document.querySelectorAll('[data-question]').forEach(b=>b.disabled=false);$('#answer').setAttribute('aria-busy','false');$('#ask button').disabled=false;}}
}
function bindSources(){document.querySelectorAll('[data-source]').forEach(a=>a.onclick=e=>{e.preventDefault();document.querySelectorAll('.highlight').forEach(x=>x.classList.remove('highlight'));const s=$('#source-'+a.dataset.source);s.classList.add('highlight');s.scrollIntoView({behavior:'smooth',block:'center'});s.focus({preventScroll:true});});}
function play(restart){try{if(native){native.speak(audioText(result),lang,+$('#speed').value,restart);return;}if(!restart&&globalThis.speechSynthesis?.paused){speechSynthesis.resume();$('#audio-status').textContent='Playing';return;}const u=speechService.play(audioText(result),lang,+$('#speed').value);$('#audio-status').textContent='Playing';u.onend=()=>{if($('#audio-status'))$('#audio-status').textContent='Finished';};u.onerror=()=>{if($('#audio-status'))$('#audio-status').textContent='Audio could not play. Please retry or read the text.';};}catch(e){$('#audio-status').textContent=e.message;}}
function answer(i){if(!current.demo){askLive(['Explain the medical terms in this report.','Which results are outside the reference ranges explicitly printed in this report?','What should I ask my doctor about this report?','Does the report explicitly recommend a follow-up?'][i]);return;}const e=result;let text='',ref=null;if(i===0)text=e.labels.terms+': '+e.terms;if(i===1){text=current.id==='blood'?e.findings[0].text+' '+e.findings[0].value:'No lab values or reference ranges are listed in this sample. This does not prove overall health.';ref=current.id==='blood'?1:0;}if(i===2)text=e.questions;if(i===3){text=e.follow;ref=e.followRef;}$('#answer').className='answer';$('#answer').innerHTML=`<div lang="${lang}">${esc(text)}</div>${ref!==null?source(ref):'<small>General education / suggested question</small>'}`;bindSources();}
function stored(){try{const raw=native?native.getHistory():localStorage.getItem('healthclear-samples')||'[]';if(raw==='null')throw Error();const parsed=JSON.parse(raw);if(!Array.isArray(parsed))throw Error();return parsed.filter(x=>(x.live&&typeof x.text==='string'&&x.result)||reports[x.id]);}catch{toast('Saved reports could not be read. They have not been overwritten.');return null;}}
function writeHistory(items){if(native){if(!native.saveHistory(JSON.stringify(items)))throw Error('Could not encrypt or save the report.');}else localStorage.setItem('healthclear-samples',JSON.stringify(items));}
function save(){try{if(!current.demo&&!native)throw Error('Encrypted personal history is available in the Android app only.');const items=stored();if(!items)throw Error('History is unreadable; export your current summary instead.');if(items.length>=20)throw Error('History contains 20 reports. Delete an older entry before saving.');items.push(current.demo?{id:current.id,lang,date:new Date().toISOString()}:{live:true,name:current.name,text:current.text,result,lang,date:new Date().toISOString()});writeHistory(items);toast('Saved on this device. You can delete it in My Reports.');}catch(e){toast(e.message);}}
function history(){clear();const items=stored();$('#app').innerHTML=`<div class="eyebrow">Your space for clarity</div><h1>My Reports</h1><p>Only reports you chose to save appear here. Personal history is encrypted on Android. Original files are not saved.</p><section class="card">${items===null?'<p role="alert">Saved history could not be decrypted. Clear saved data in Settings only if you want to remove it.</p>':items.length?items.map((r,i)=>`<div class="history-item"><div><strong>${esc(r.live?r.name:reports[r.id].name)}</strong><p class="fine">${r.live?'Saved report':'Fictional sample'} · ${esc(r.lang.toUpperCase())}</p></div><div><button data-open="${i}">Open</button> <button data-delete="${i}">Delete</button></div></div>`).join(''):'<div class="empty"><div class="upload-icon">▤</div><h2>Your reports, in one place.</h2><p>Reports are saved only when you choose Save to My Reports.</p><a class="button primary" href="#upload">Start with a report →</a></div>'}</section>`;
 mountCloudHistory();
 document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{const r=items[+b.dataset.open];lang=r.lang;if(r.live){current={name:r.name,text:r.text,result:r.result,resultLang:r.lang,demo:false,saved:true,consent:false};if(connection.ready){showSavedConsent();return;}}else current={id:r.id,name:reports[r.id].name,text:reports[r.id].lines.join('\n'),demo:true};results();});
 document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{try{items.splice(+b.dataset.delete,1);writeHistory(items);history();toast('Saved report deleted.');}catch(e){toast(e.message);}});
}
function showSavedConsent(){results();const box=document.createElement('div');box.className='banner';box.innerHTML='<label class="consent"><input type="checkbox" id="saved-consent">Allow this saved report text to be sent to my backend and OpenAI for new translations and questions. Provider retention applies.</label>';$('#app').prepend(box);$('#saved-consent').onchange=e=>current.consent=e.target.checked;}
function settings(){clear();$('#app').innerHTML=`<div class="eyebrow">You are in control</div><h1>Settings & privacy</h1><section class="card developer-card" aria-labelledby="developer-heading"><div class="developer-avatar" aria-hidden="true">PB</div><div><span class="eyebrow">About the developer</span><h2 id="developer-heading">Punit Badyal</h2><p>Developer of HealthClear — helping people understand written medical reports in simple language.</p><a class="button" href="https://github.com/punitbadyal01-blip" rel="noopener noreferrer">View my GitHub ↗</a><p class="fine">GitHub · @punitbadyal01-blip</p></div></section>
 <section class="card backend-card"><h2>Connect your report service</h2><p>Use your deployed HealthClear backend. Never enter an AI provider key here. The server URL is saved; your backend access token stays in memory until the app closes or you disconnect.</p><form id="connect"><label for="backend-url">${native?.localDevelopment?.()?'Backend address (USB development: http://127.0.0.1:8080)':'Backend HTTPS address'}</label><input id="backend-url" type="url" value="${esc(connection.url)}" required placeholder="https://your-backend.example.com" autocomplete="off"><label for="backend-token">Backend access token</label><input id="backend-token" type="password" required minlength="32" autocomplete="off" placeholder="Token set by your backend administrator"><div class="toolbar"><button class="primary">Connect & test</button><button type="button" id="disconnect">Disconnect</button></div></form><div id="connection-message" role="status">${connection.ready?'Connected for this session.':'Not connected. Fictional samples remain available offline.'}</div></section>
 <div class="workspace"><section class="card"><h2>Privacy & control</h2><p>No-save is the default. With your explicit consent, reports and questions are sent to your configured backend and OpenAI. This backend does not write medical files, text, or responses to disk or logs. It sends provider requests with storage disabled. Provider abuse-monitoring retention may still apply, typically up to 30 days with exceptions; review your provider agreement before handling personal data.</p><p>Android caches PDFs and camera captures privately while viewing, then removes them when you leave the report or at the next launch after an interrupted session. Explicitly saved reviewed text and explanations are encrypted with Android Keystore. Original files are not saved. Backups are disabled. Anyone who can unlock your device and open this app can view your saved reports.</p><p>Optional Supabase accounts store only report text you explicitly choose to upload. Cloud reports remain until deleted; uninstalling does not delete cloud data. Provider backups may retain deleted data under your project retention settings. Delete cloud reports in My Reports or delete your account below. Local history is separate. No training consent or compliance certification is claimed.</p><button id="erase">Delete all saved reports</button><div id="erase-confirm" hidden><p>This permanently removes saved report text and explanations from this device.</p><button id="erase-yes">Delete saved reports</button><button id="erase-no">Cancel</button></div></section><section class="card sample-card"><h2>How it works</h2><p><strong>Online:</strong> written-text extraction, English/Hindi/Telugu explanations and source-linked questions through your configured backend.</p><p><strong>On your device:</strong> document selection, camera, PDF viewing, encrypted history and summary export.</p><p><strong>Audio:</strong> Android uses installed offline language voices. Missing voices have a readable fallback. Browser preview may use network-backed speech.</p><p>AI can make errors. Review extracted text before analysis. Medical scan images without a written report are not interpreted.</p><p class="fine">HealthClear 1.3 · Android 8 or later</p></section></div>`;
 mountCloudAccount();
 $('#connect').onsubmit=async e=>{e.preventDefault();const button=$('#connect button');button.disabled=true;$('#connection-message').textContent='Checking your backend…';try{cloudSession='';cloudEmail='';connection.configure($('#backend-url').value,$('#backend-token').value);const status=await api('status');if(!status.configured&&!status.cloudConfigured)throw Error('Backend is reachable, but AI and Supabase are not configured.');if(page!=='settings')return;$('#backend-token').value='';$('#connection-message').textContent=`Connected. AI: ${status.configured?'ready':'not configured'}. Supabase: ${status.cloudConfigured?'ready':'not configured'}.`;mountCloudAccount();}catch(err){connection.disconnect();if($('#connection-message'))$('#connection-message').textContent=err.message;}finally{button.disabled=false;}};
 $('#disconnect').onclick=()=>{cloudSession='';cloudEmail='';connection.disconnect();mountCloudAccount();$('#backend-token').value='';$('#connection-message').textContent='Disconnected. Your session token has been cleared.';};
 $('#erase').onclick=()=>$('#erase-confirm').hidden=false;$('#erase-no').onclick=()=>$('#erase-confirm').hidden=true;$('#erase-yes').onclick=()=>{try{if(native){if(!native.clearHistory())throw Error();}localStorage.removeItem('healthclear-samples');$('#erase-confirm').hidden=true;toast('All saved reports deleted.');}catch{toast('Could not delete saved data. Please retry.');}};
}
function download(){const r=current.demo?reports[current.id]:{lines:current.text.split(/\r?\n/)};const text=(current.demo?'HEALTHCLEAR — FICTIONAL DEMO':'HEALTHCLEAR — AI-GENERATED EXPLANATION')+'\nDoctor-visit discussion summary\nNot a diagnosis or treatment plan.\n\n'+audioText(result)+'\n\nSOURCE REPORT\n'+r.lines.map((s,i)=>`[${i+1}] ${s}`).join('\n')+'\n\nTRACEABILITY\n'+result.findings.map(f=>`${f.text} → [${f.ref+1}]`).join('\n')+`\n${result.follow} → [${(result.followRefs||[result.followRef]).filter(x=>x!==null).map(x=>x+1).join(', ')||'not specified'}]\nDefinitions and doctor questions are general education.`;if(native){native.exportSummary(text);return;}const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='HealthClear-doctor-summary.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Doctor-visit summary downloaded.');}
window.healthclearNativeError=toast;
window.healthclearAudioStatus=text=>{if($('#audio-status'))$('#audio-status').textContent=text;};
window.healthclearReceiveFile=(base64,name,type,pages)=>{const bytes=Uint8Array.from(atob(base64),c=>c.charCodeAt(0));loadFile(new File([bytes],name,{type}));};
window.healthclearPdfPage=(url,index,count)=>{if(!$('#pdf-page'))return;current.pdfPage=index;$('#pdf-page').src=url;$('#pdf-number').textContent=`Page ${index+1} of ${count}`;$('#pdf-prev').disabled=index===0;$('#pdf-next').disabled=index===count-1;};
window.healthclearAndroidBack=()=>{if(page==='results')review();else if(page==='review')upload();else if(page!=='upload')render('upload');else native?.finishApp();};
document.addEventListener('click',e=>{const a=e.target.closest('a[href]');const route=a?.getAttribute('href')?.slice(1);if(['upload','history','settings'].includes(route)){e.preventDefault();window.history.replaceState(null,'','#'+route);render(route);}});
window.addEventListener('hashchange',()=>render(location.hash.slice(1)));window.addEventListener('pagehide',clear);render(location.hash.slice(1)||'upload');

async function cloudCall(action,body={}){return api('cloud',{...body,action,session:cloudSession});}
function mountCloudAccount(){
 $('#cloud-account')?.remove();
 const box=document.createElement('section');box.id='cloud-account';box.className='card backend-card';
 box.innerHTML=`<h2>Cloud account · Supabase</h2><p>Optional. Connect your backend above first. Only explicitly saved reviewed text is stored in your private cloud account. Original files and explanations are not uploaded to the database. Reopening text lets you review it and request a fresh explanation.</p><p class="fine">Your session stays in memory. Sign in again after closing the app or when your session expires. Local saved reports remain separate.</p>${cloudSession?`<p>Signed in as ${esc(cloudEmail)}</p><button id="cloud-logout">Sign out</button><details><summary>Delete cloud account</summary><p>Permanently deletes your cloud account and saved cloud reports. Local reports and exported copies remain. Database backups follow the Supabase project retention policy.</p><label for="delete-account-confirm">Type DELETE to confirm</label><input id="delete-account-confirm" autocomplete="off"><button id="cloud-delete-account">Delete account and cloud reports</button></details>`:`<form id="cloud-login"><label for="cloud-email">Email</label><input id="cloud-email" type="email" required maxlength="254" autocomplete="username"><label for="cloud-password">Password (at least 12 characters)</label><input id="cloud-password" type="password" required minlength="12" maxlength="128" autocomplete="current-password"><div class="toolbar"><button class="primary" name="action" value="login">Sign in</button><button name="action" value="signup">Create account</button></div><p>Account creation sends your email and password securely to Supabase through your backend. Confirm your email before signing in.</p></form>`}<p id="cloud-account-status" role="status"></p>`;
 $('#app').append(box);
 const message=text=>{if($('#cloud-account-status'))$('#cloud-account-status').textContent=text;};
 if($('#cloud-login'))$('#cloud-login').onsubmit=async event=>{event.preventDefault();const action=event.submitter?.value||'login',email=$('#cloud-email').value,password=$('#cloud-password').value;box.querySelectorAll('button').forEach(b=>b.disabled=true);message('Connecting securely…');try{const data=await cloudCall(action,{email,password});if(!box.isConnected)return;cloudSession=data.session||'';cloudEmail=data.email||'';mountCloudAccount();message(data.message);}catch(e){message(e.message);}finally{box.querySelectorAll('button').forEach(b=>b.disabled=false);if($('#cloud-password'))$('#cloud-password').value='';}};
 if($('#cloud-logout'))$('#cloud-logout').onclick=async()=>{try{await cloudCall('logout');}catch{toast('Signed out on this device. Server session revocation could not be confirmed.');}finally{cloudSession='';cloudEmail='';if(page==='settings')mountCloudAccount();}};
 if($('#cloud-delete-account'))$('#cloud-delete-account').onclick=async()=>{const confirm=$('#delete-account-confirm').value;if(confirm!=='DELETE'){message('Type DELETE to confirm.');return;}$('#cloud-delete-account').disabled=true;try{await cloudCall('delete-account',{confirm});cloudSession='';cloudEmail='';if(page==='settings')mountCloudAccount();toast('Cloud account and cloud reports deleted. Local history remains on this device.');}catch(e){message(e.message);if($('#cloud-delete-account'))$('#cloud-delete-account').disabled=false;}};
}
async function saveCloud(){
 if(!cloudSession){toast('Sign in to your optional cloud account in Settings first.');return;}
 if(current.demo){toast('Cloud saving is for your reviewed personal report text. Samples remain available offline.');return;}
 if($('#cloud-save-confirm'))return;
 const target=current,box=document.createElement('div');box.id='cloud-save-confirm';box.className='banner';box.innerHTML='<p>Save this reviewed report text and filename to your private Supabase account? It will remain until you delete it. The original file and explanation will not be saved to the cloud.</p><button id="cloud-save-yes">Save text to my cloud account</button> <button id="cloud-save-no">Cancel</button><p role="status"></p>';$('#app').prepend(box);
 $('#cloud-save-no').onclick=()=>box.remove();$('#cloud-save-yes').onclick=async()=>{box.querySelectorAll('button').forEach(b=>b.disabled=true);try{await cloudCall('save',{saveConsent:true,report:{name:target.name.slice(0,200),text:target.text,language:lang}});box.remove();toast('Report text saved to your cloud account.');}catch(e){box.querySelector('p[role]').textContent=e.message;box.querySelectorAll('button').forEach(b=>b.disabled=false);}};
}
function mountCloudHistory(){
 const box=document.createElement('section');box.className='card backend-card';box.innerHTML='<h2>Cloud reports</h2><p>Reviewed text saved to your Supabase account. Local reports above stay on this device.</p><div id="cloud-list" role="status"></div>';$('#app').append(box);
 const list=$('#cloud-list');
 if(!cloudSession){list.innerHTML='<p>Sign in through Settings to view your cloud reports.</p>';return;}
 let offset=0;
 async function refresh(){list.textContent='Loading cloud reports…';try{const data=await cloudCall('list',{offset});if(!box.isConnected)return;list.innerHTML=data.reports.length?data.reports.map(r=>`<div class="history-item"><div><strong>${esc(r.name)}</strong><p>${esc(r.language)} · ${esc(new Date(r.created_at).toLocaleDateString())}</p></div><div><button data-cloud-open="${esc(r.id)}">Review text</button><button data-cloud-delete="${esc(r.id)}">Delete</button></div></div>`).join(''):'<p>No cloud reports yet. Saving is always optional.</p>';
 if(offset>0){const previous=document.createElement('button');previous.textContent='Previous 100';previous.onclick=()=>{offset=Math.max(0,offset-100);refresh();};list.append(previous);}
 if(data.reports.length===100){const next=document.createElement('button');next.textContent='Next 100';next.onclick=()=>{offset+=100;refresh();};list.append(next);}
 list.querySelectorAll('[data-cloud-open]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const data=await cloudCall('open',{id:b.dataset.cloudOpen});if(!box.isConnected)return;const r=data.report;lang=r.language;current={name:r.name,text:r.text,demo:false,saved:true,consent:false};review();const consent=document.createElement('div');consent.className='banner';consent.innerHTML='<label><input type="checkbox" id="cloud-processing-consent"> Allow this report text to be sent to my backend and AI provider for a new explanation. Provider retention applies.</label>';$('#app').prepend(consent);$('#cloud-processing-consent').onchange=e=>current.consent=e.target.checked;}catch(e){toast(e.message);b.disabled=false;}});
 list.querySelectorAll('[data-cloud-delete]').forEach(b=>b.onclick=async()=>{if(b.dataset.confirm!=='yes'){b.dataset.confirm='yes';b.textContent='Confirm delete';return;}b.disabled=true;try{await cloudCall('delete',{id:b.dataset.cloudDelete});await refresh();}catch(e){toast(e.message);b.disabled=false;}});
 }catch(e){if(!box.isConnected)return;list.textContent=e.message;const retry=document.createElement('button');retry.textContent='Retry';retry.onclick=refresh;list.append(retry);}}
 refresh();
}
